/**
 * Builds tests/pdf-pictures.pdf for Save All Images in PDF (docs/archive/pdf-and-audit-plan.md,
 * Phase 2b): two pages holding
 *   page 1  a 320x200 JPEG photo, a 16x16 icon, and a 96x48 logo
 *   page 2  the same logo again, and a 200x120 PNG with a transparent hole
 * so a run with the defaults saves the photo (as its original JPEG bytes), the logo once,
 * and the transparent picture, and skips the icon. Generated by headless Chromium, which
 * embeds a JPEG <img> as its own JPEG stream.
 *
 *   node tests/make-pdf-pictures.mjs
 */
import path from 'path';
import { fileURLToPath } from 'url';
import puppeteer from 'puppeteer';

const here = path.dirname(fileURLToPath(import.meta.url));
const html = `<!doctype html><html><head><meta charset="utf-8"><style>
  body { font-family: Georgia, serif; font-size: 16px; margin: 1.5cm; }
  .p { page-break-after: always; }
  .p:last-child { page-break-after: auto; }
  img { display: block; margin: 10px 0; }
</style></head><body>
  <div class="p"><p>Pictures fixture, page one.</p>
    <img id="photo" width="320" height="200"><img id="icon" width="16" height="16"><img class="logo" width="96" height="48"></div>
  <div class="p"><p>Pictures fixture, page two.</p>
    <img class="logo" width="96" height="48"><img id="hole" width="200" height="120"></div>
  <script>
    function canvas(w, h, draw) { const c = document.createElement('canvas'); c.width = w; c.height = h; draw(c.getContext('2d')); return c; }
    const photo = canvas(320, 200, g => {
      const grd = g.createLinearGradient(0, 0, 320, 200); grd.addColorStop(0, '#1E6091'); grd.addColorStop(1, '#F4A259');
      g.fillStyle = grd; g.fillRect(0, 0, 320, 200);
      g.fillStyle = '#FFFFFF'; g.beginPath(); g.arc(230, 70, 36, 0, 7); g.fill();
      g.fillStyle = '#2D6A4F'; g.fillRect(0, 150, 320, 50);
    });
    document.getElementById('photo').src = photo.toDataURL('image/jpeg', 0.9);
    document.getElementById('icon').src = canvas(16, 16, g => { g.fillStyle = '#C0392B'; g.fillRect(0, 0, 16, 16); }).toDataURL('image/png');
    const logo = canvas(96, 48, g => { g.fillStyle = '#34495E'; g.fillRect(0, 0, 96, 48); g.fillStyle = '#F1C40F'; g.fillRect(12, 12, 72, 24); }).toDataURL('image/png');
    document.querySelectorAll('.logo').forEach(i => i.src = logo);
    document.getElementById('hole').src = canvas(200, 120, g => {
      g.fillStyle = '#8E44AD'; g.fillRect(0, 0, 200, 120); g.clearRect(60, 30, 80, 60);
    }).toDataURL('image/png');
  </script>
</body></html>`;

const browser = await puppeteer.launch({ headless: 'new' });
try {
    const page = await browser.newPage();
    await page.setContent(html, { waitUntil: 'load' });
    await page.evaluate(() => Promise.all(Array.from(document.images).map(i => i.decode())));
    await page.pdf({ path: path.join(here, 'pdf-pictures.pdf'), format: 'A5', printBackground: true });
    console.log('wrote tests/pdf-pictures.pdf');
} finally { await browser.close(); }
